F14.P3.fragment:
interface Shape { fun area(): Double }
class Circle(val r: Double) : Shape { override fun area() = 3.141592653589793 * r * r }
class Rect(val w: Double, val h: Double) : Shape { override fun area() = w * h }
class Tri(val b: Double, val h: Double) : Shape { override fun area() = 0.5 * b * h }
val shape: Shape = Tri(4.0, 3.0)
val result = shape.area()

